response.content:
## Analysis

The issue is that `MutableHeaders` (and its parent `Headers`) don't implement the merge operators `|` and `|=` introduced for dicts in Python 3.9. The fix is to add `__or__` and `__ior__` methods to the `Headers` class in `starlette/datastructures.py`, so both `Headers` and `MutableHeaders` support merging with a plain mapping.

- `__or__` returns a *new* `Headers` instance containing the merged headers.
- `__ior__` mutates in place (using the existing `update()` method) and returns `self`, which works correctly for `MutableHeaders` (and for `Headers` it still functions, though mutation is only meaningful on the mutable subclass).

## Patch

```diff
--- a/starlette/datastructures.py
+++ b/starlette/datastructures.py
@@ -528,6 +528,14 @@ class Headers(typing.Mapping[str, str]):
     def __repr__(self) -> str:
         class_name = self.__class__.__name__
         encoding = self.encoding or "utf-8"
         return f"{class_name}({self.mutable!r}, {dict(self)!r})"
+
+    def __or__(self, other: typing.Mapping[str, str]) -> "Headers":
+        if not isinstance(other, typing.Mapping):
+            raise TypeError(f"Expected a mapping but got {type(other).__name__!r}")
+        return Headers({**self, **other})
+
+    def __ior__(self, other: typing.Mapping[str, str]) -> "Headers":
+        if not isinstance(other, typing.Mapping):
+            raise TypeError(f"Expected a mapping but got {type(other).__name__!r}")
+        self.update(other)
+        return self
```

## Resulting code

The relevant section of `starlette/datastructures.py` after the change:

```python
class Headers(typing.Mapping[str, str]):
    def __init__(
        self,
        headers: typing.Optional[
            typing.Mapping[str, str]
        ] = None,  # type: ignore
        raw: typing.Optional[typing.List[typing.Tuple[bytes, bytes]]] = None,
        scope: typing.Optional[typing.MutableMapping[str, typing.Any]] = None,
    ) -> None:
        self._list: typing.List[typing.Tuple[bytes, bytes]] = []
        if headers is not None:
            if isinstance(headers, Headers):
                self._list = headers.rawlist()
            else:
                self._list = [
                    (key.lower().encode("latin-1"), value.encode("latin-1"))
                    for key, value in headers.items()
                ]
        elif raw is not None:
            self._list = raw
        elif scope is not None:
            # HTTP header keys are case-insensitive.
            self._list = scope["headers"] = list(scope["headers"])

    @property
    def raw(self) -> typing.List[typing.Tuple[bytes, bytes]]:
        return self._list

    def keys(self) -> typing.KeysView[str]:
        return {key.decode("latin-1") for key, value in self._list}.keys()

    def values(self) -> typing.ValuesView[str]:
        return {key: value for key, value in self._list}.values()

    def items(self) -> typing.ItemsView[str, str]:
        return {key.decode("latin-1"): value for key, value in self._list}.items()

    def get(self, key: str, default: typing.Any = None) -> typing.Any:
        try:
            return self[key]
        except KeyError:
            return default

    def getlist(self, key: str) -> typing.List[str]:
        get_header_key = key.lower().encode("latin-1")
        return [
            value.decode("latin-1")
            for key, value in self._list
            if key == get_header_key
        ]

    def mutablecopy(self) -> "MutableHeaders":
        return MutableHeaders(raw=self[:])

    def __contains__(self, key: str) -> bool:
        get_header_key = key.lower().encode("latin-1")
        for header_key, header_value in self._list:
            if header_key == get_header_key:
                return True
        return False

    def __getitem__(self, key: str) -> str:
        get_header_key = key.lower().encode("latin-1")

        for header_key, header_value in self._list:
            if header_key == get_header_key:
                return header_value.decode("latin-1")

        raise KeyError(key)

    def __iter__(self) -> typing.Iterator[typing.Any]:
        return iter(self.items())

    def __len__(self) -> int:
        return len(self._list)

    def __eq__(self, other: typing.Any) -> bool:
        try:
            other_headers = Headers(other)
        except ValueError:
            return False
        return sorted(self._list) == sorted(other_headers._list)

    def __repr__(self) -> str:
        class_name = self.__class__.__name__
        encoding = self.encoding or "utf-8"
        return f"{class_name}({self.mutable!r}, {dict(self)!r})"

    def __or__(self, other: typing.Mapping[str, str]) -> "Headers":
        if not isinstance(other, typing.Mapping):
            raise TypeError(f"Expected a mapping but got {type(other).__name__!r}")
        return Headers({**self, **other})

    def __ior__(self, other: typing.Mapping[str, str]) -> "Headers":
        if not isinstance(other, typing.Mapping):
            raise TypeError(f"Expected a mapping but got {type(other).__name__!r}")
        self.update(other)
        return self
```

