import logging
import threading
import time

from zope.interface import implementer

from zope.ramcache.interfaces import IRAMCache


logger = logging.getLogger('zope.ramcache')


@implementer(IRAMCache)
class RAMCache:
    """The RAM cache is a cache in memory that can be used anywhere.

    The cache is very fast, and is implemented with a dict...
    """

    _caches = {}
    _caches_lock = threading.Lock()
    _timestamp = None

    def __init__(self):
        self._data = {}
        self._misses = 0
        self._accesses = 0
        self._last_clear = time.time()

    def _createKey(self, request, **kwargs):
        if request is not None:
            request = str(request)
        else:
            request = ''
        return (request, tuple(sorted(kwargs.items())))

    def get(self, object, request=None, **kwargs):
        key = self._createKey(request, **kwargs)
        cache = self._getStorage(object)
        with cache.lock:
            entry = cache.getEntry(key)
        if entry is None:
            self._misses += 1
            return None
        self._accesses += 1
        return entry.value

    def set(self, data, object=None, request=None, **kwargs):
        key = self._createKey(request, **kwargs)
        cache = self._getStorage(object)
        with cache.lock:
            cache.storeEntry(_CacheEntry(key, data))

    def query(self, object, default=None, request=None, **kwargs):
        result = self.get(object, request, **kwargs)
        if result is None:
            return default
        return result

    def invalidate(self, object=None, request=None, **kwargs):
        if object is None:
            self.invalidateAll()
            return
        key = self._createKey(request, **kwargs)
        cache = self._getStorage(object)
        with cache.lock:
            cache.invalidate(key)

    def invalidateAll(self):
        self._data = {}
        self._last_clear = time.time()

    def getStatistics(self):
        """ See IRAMCache. """
        result = {}
        for object, cache in self._data.items():
            with cache.lock:
                stats = cache.getStatistics()
            result[object] = stats
        return result

    def _getStorage(self, object):
        if object is None:
            object = ''
        else:
            object = str(object)
        try:
            return self._data[object]
        except KeyError:
            self._data[object] = storage = _Storage()
            return storage


